    "pt": { "t": "Prisão de ventre ou inchaço", "q": "prisão de ventre intestino preso gases inchaço inchaco barriga inchada barriga estufada não consigo evacuar constipação", "a": "Pouca ingestão de líquidos, menos atividade e a dieta espacial deixam o intestino mais lento.", "s": ["Beba pelo menos 2 L por dia.","Escolha itens do cardápio ricos em fibras e frutas.","Faça exercício todos os dias."], "e": "Dor abdominal forte, febre ou 4 ou mais dias sem evacuar: oficial médico da tripulação." },
    "fr": { "t": "Constipation ou ballonnements", "q": "constipation ballonnements gaz ventre gonflé ventre ballonné transit lent je n’arrive pas à aller à la selle estomac gonflé", "a": "Boire peu, bouger moins et le régime spatial ralentissent l’intestin.", "s": ["Buvez au moins 2 L par jour.","Choisissez des plats du menu riches en fibres et des fruits.","Faites de l’exercice tous les jours."], "e": "Douleur abdominale intense, fièvre ou 4 jours ou plus sans selles : officier médical de l’équipage." }
