  "MED-18": {
    "es": { "t": "Medicamentos en el espacio", "q": "medicamentos medicinas pastillas puedo tomar pastilla dosis caducidad vencimiento interacciones alergia a medicamento remedio fármaco farmaco", "a": "Algunos medicamentos pierden potencia más rápido en el espacio (radiación, temperatura). El motor de reglas verifica alergias, interacciones y dosis; las existencias salen del inventario de la nave.", "s": ["Usa la verificación de medicamentos de Preguntas antes de tomar cualquier medicamento («¿Puedo tomar …?»).","Verifica la fecha de caducidad de la etiqueta.","Anota lo que tomaste en el inventario de la nave (Usar uno)."], "e": "Si dudas de una dosis o el medicamento no hizo efecto: pregunta al oficial médico de la tripulación." },
    "pt": { "t": "Medicamentos no espaço", "q": "medicamentos remédios remedios comprimido posso tomar dose validade vencimento interações alergia a medicamento pílula fármaco farmaco", "a": "Alguns medicamentos perdem potência mais rápido no espaço (radiação, temperatura). O motor de regras verifica alergias, interações e dose; o estoque vem do inventário da nave.", "s": ["Use a verificação de medicamentos em Perguntas antes de qualquer medicamento (“Posso tomar …?”).","Confira a data de validade no rótulo.","Registre o que tomou no inventário da nave (Usar um)."], "e": "Dúvida sobre a dose ou o medicamento não fez efeito: pergunte ao oficial médico da tripulação." },
    "fr": { "t": "Médicaments dans l’espace", "q": "médicaments medicaments cachet comprimé puis-je prendre dose date de péremption interactions allergie à un médicament pilule remède", "a": "Certains médicaments perdent de leur efficacité plus vite dans l’espace (rayonnements, température). Le moteur de règles vérifie les allergies, les interactions et la dose ; les stocks viennent de l’inventaire du vaisseau.", "s": ["Utilisez la vérification des médicaments de Questions avant tout médicament (« Puis-je prendre … ? »).","Vérifiez la date de péremption sur l’étiquette.","Notez ce que vous avez pris dans l’inventaire du vaisseau (Utiliser un)."], "e": "Doute sur une dose ou médicament sans effet : demandez à l’officier médical de l’équipage." }
  },
